const prayerCfg=()=>{const p={...PRAYER_DEFAULT,...(state.prayer&&typeof state.prayer==="object"?state.prayer:{})};["fajr","duhr","jumua","asr","maghrib","isha"].forEach(k=>p[k]=cleanTime(p[k]));p.minutes=Math.min(120,Math.max(5,Number(p.minutes)||30));p.on=!!p.on;p.auto=!!p.auto;return p;};
