function updatePackageField(){const box=$("fPackage"),row=$("fPackageRow"),lesson=$("fType").value==="Lesson",cur=pkgs().find(p=>p.id===box.dataset.entry),typed=$("fStudent").value.trim(),byPhone=findPhone($("fPhone").value||(isPhone(typed)?typed:"")),p=cur||activePkg(typed&&!isPhone(typed)?typed:byPhone?.name);row.classList.toggle("hidden",!lesson||!p);box.dataset.id=p?p.id:"";if(p){$("fPackageText").textContent=`Use package (${pkgLeft(p).toFixed(1)}h left)`;if(box.dataset.entry===undefined||box.dataset.entry==="")box.checked=true;}}
