function monthRows(){const n=new Date(),out=[];for(let i=11;i>=0;i--){const d=new Date(n.getFullYear(),n.getMonth()-i,1),key=dateISO(d).slice(0,7),t=totals(state.entries.filter(e=>e.date.startsWith(key)));out.push({key,short:d.toLocaleDateString("en-GB",{month:"short"}),long:d.toLocaleDateString("en-GB",{month:"long",year:"numeric"}),income:t.income,expenses:t.expenses,profit:t.income-t.expenses});}return out;}
