$("recordForm").addEventListener("submit",ev=>{ev.preventDefault();const type=$("fType").value,lesson=type==="Lesson",editing=!!$("recordId").value,id=$("recordId").value||uid();const old=state.entries.find(x=>x.id===id),keep=f=>old&&old.type===type?(old[f]??0):0;// hidden boxes: keep the old value only if the type did not change
const e={id,date:$("fDate").value,type,student:$("fStudent").value.trim(),start:lesson?$("fStart").value:"",end:lesson?$("fEnd").value:"",rate:$("fRate").value===""?DEFAULT_RATE:num($("fRate").value),cost:!lesson&&type!=="Note"?num($("fCost").value):keep("cost"),paid:lesson?$("fPaid").checked:true,km:type==="Fuel"?num($("fKm").value):keep("km"),comment:$("fComment").value.trim()};const baseRate=e.rate,box=$("fPackage"),pk=lesson&&box.checked&&!$("fPackageRow").classList.contains("hidden")?pkgs().find(p=>p.id===box.dataset.id):null;if(pk){e.rate=pkgRate(pk);e.paid=true;e.pkg=pk.id;}if(lesson&&!editing&&!e.student&&!$("fPhone").value.trim()){$("recordError").textContent="Add a name or a phone number.";return;}if(lesson){const noTimes=!e.start&&!e.end,h=hours(e);if(!(noTimes&&editing)&&(!e.start||!e.end||h<=0||h>12)){$("recordError").textContent="Check the times: a lesson needs a start and an end, and can be at most 12 hours.";return;}const clash=noTimes?null:lessonsOn(e.date).find(x=>x.id!==id&&x.start&&x.end&&toMin(e.start)<toMin(x.end)&&toMin(x.start)<toMin(e.end));if(clash&&!confirm(`${timeText(clash)} is already booked for ${clash.student||"another lesson"}. Save anyway?`))return;const pray=noTimes?null:prayerBlocks(e.date).find(b=>toMin(e.start)<toMin(b.end)&&toMin(b.start)<toMin(e.end));if(pray&&!confirm(`This lesson overlaps ${pray.name} (${pray.start}–${pray.end}). Save anyway?`))return;}if(lesson&&(e.student||$("fPhone").value.trim()))e.student=resolveStudent(e.student,$("fPhone").value);const i=state.entries.findIndex(x=>x.id===id);if(i>=0)state.entries[i]=e;else state.entries.push(e);const weeks=lesson&&!editing?Number($("fRepeat").value)||1:1;let booked=1,skipped=0,noPkg=0;for(let k=1;k<weeks;k++){const[y,m,d]=e.date.split("-").map(Number),date=dateISO(new Date(y,m-1,d+7*k));if(conflictOn(date,e.start,e.end,""))skipped++;else{const copy={...e,id:uid(),date,paid:false};if(pk){if(pkgLeft(pk)+.001>=hours(e))copy.paid=true;else{delete copy.pkg;copy.rate=baseRate;noPkg++;}}state.entries.push(copy);booked++;}}save();$("recordDialog").close();toast(weeks>1?`${booked} lessons booked, ${skipped} skipped because the time was taken${noPkg?`, ${noPkg} not on the package (no hours left)`:""}`:"Record saved");});
