function csvRows(text){const rows=[];let row=[],field="",quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===","&&!quoted){row.push(field);field="";}else if((c==="\n"||c==="\r")&&!quoted){if(c==="\r"&&text[i+1]==="\n")i++;row.push(field);if(row.some(x=>x!==""))rows.push(row);row=[];field="";}else field+=c;}if(field||row.length){row.push(field);rows.push(row);}return rows;}
const uncell=v=>String(v??"").replace(/^'(?=[=+\-@\t\r])/,"");
function headerIs(row,cols){return !!row&&cols.every((c,i)=>(row[i]||"").trim().toLowerCase()===c);}
function importLog(text){const rows=csvRows(text.replace(/^\uFEFF/,""));if(!headerIs(rows[0],["date","type","student","start","end"])){toast("Nothing imported: this is not a Log CSV file.");return;}let added=0,dup=0,skip=0;const seen=new Set(state.entries.map(key));for(const c of rows.slice(1)){if(c.length<11||!TYPES.includes(c[1]||"Lesson")){skip++;continue;}const d=parseDate(c[0]);if(!d){skip++;continue;}const date=dateISO(d);const e={id:uid(),date,type:c[1]||"Lesson",student:uncell(c[2]),start:cleanTime(c[3]),end:cleanTime(c[4]),rate:(c[6]||"").trim()===""?DEFAULT_RATE:num(c[6]),cost:num(c[8]),paid:["yes","true","1","paid","y"].includes((c[9]||"").toLowerCase()),km:num(c[10]),comment:uncell(c[11])};if(e.type==="Lesson"&&e.start&&e.end&&(hours(e)<=0||hours(e)>12)){skip++;continue;}if(seen.has(key(e))){dup++;continue;}seen.add(key(e));state.entries.push(e);added++;}save();toast(`Log imported: ${added} added, ${dup} duplicates skipped, ${skip} invalid`);}
function importStudents(text){const rows=csvRows(text.replace(/^\uFEFF/,""));if(!headerIs(rows[0],["name","phone"])){toast("Nothing imported: this is not a Students CSV file.");return;}let added=0,dup=0;const seen=new Set(state.students.map(s=>s.name.trim().toLowerCase()));for(const c of rows.slice(1)){const name=uncell(c[0]).trim();if(!name)continue;const k=name.toLowerCase();if(seen.has(k)){dup++;continue;}seen.add(k);state.students.push({id:uid(),name,phone:uncell(c[1]).trim(),notes:uncell(c[2])});added++;}save();toast(`Students imported: ${added} added, ${dup} duplicates skipped`);}
async function download(name,content,type){const file=new File([content],name,{type}),installed=matchMedia("(display-mode: standalone)").matches||navigator.standalone===true;if(installed&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file]});return true;}catch(err){if(err.name==="AbortError")return false;}}const a=document.createElement("a"),url=URL.createObjectURL(file);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);return true;}
// A leading ' stops Excel from running text such as "=..." or "+351..." as a formula. Import removes it again.
