function validBackup(d){return !!d&&Array.isArray(d.entries)&&Array.isArray(d.students)&&d.entries.every(x=>x&&x.id&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&typeof x.type==="string")&&d.students.every(x=>x&&x.id&&typeof x.name==="string")&&(d.packages==null||Array.isArray(d.packages)&&d.packages.every(p=>p&&p.id&&typeof p.student==="string"&&Number(p.hours)>0));}
